def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Start of a new field
        if i == len(line):
            # End of line
            if i == 0:
                # Empty line case
                fields.append("")
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        if i < len(line) and line[i] != ',':
                            # Closing quote not followed by comma or end of line
                            return None
                        if i < len(line):
                            i += 1  # Skip comma
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Unterminated quoted field
                return None
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Quote in unquoted field is malformed
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < len(line):
                i += 1  # Skip comma

    return fields

